export const factorData={light:{name:'Light intensity',unit:'relative units',x:[0,20,40,60,80,100],y:[0,2,4,6,6,6],reason:'light',why:'More light can raise rate until the curve flattens under these conditions.'},co2:{name:'CO₂ concentration',unit:'%',x:[0,.02,.04,.06,.08],y:[0,2,4,5,5],reason:'reactant',why:'CO₂ supplies a reactant; increases can raise rate before the tested curve flattens.'},temperature:{name:'Temperature',unit:'°C',x:[5,15,25,35,45],y:[1,3,6,4,0],reason:'enzyme',why:'Warming can increase enzyme-controlled rate, but excessive heat can denature enzymes.'},chlorophyll:{name:'Chlorophyll amount',unit:'relative %',x:[0,25,50,75,100],y:[0,1.5,3,4.5,6],reason:'absorb',why:'Less chlorophyll means less useful light absorption in this matched comparison.'}};
export function comparisonDirection(a,b){return a>b?'increase':a<b?'decrease':'same';}
export function inverseIntensity(distance,reference=10,intensity=100){return Number.isFinite(Number(distance))&&Number(distance)>0?intensity*(reference/Number(distance))**2:null;}
export function gasRate(volume,time){return Number.isFinite(Number(volume))&&Number.isFinite(Number(time))&&Number(volume)>=0&&Number(time)>0?Number(volume)/Number(time):null;}
export const mean=a=>Array.isArray(a)&&a.length&&a.every(Number.isFinite)?a.reduce((s,n)=>s+n,0)/a.length:null;
export const pondTrials={10:[11,12,13],20:[7,8,9],30:[3,4,5],40:[1,2,3]};
export const pondRates=Object.entries(pondTrials).map(([d,a])=>[Number(d),mean(a)/2]);
export const multiCurves=[{id:'low',name:'Low CO₂,20°C',points:[[0,0],[20,2],[40,3],[60,3],[80,3],[100,3]]},{id:'co2',name:'Higher CO₂,20°C',points:[[0,0],[20,2],[40,4],[60,6],[80,6],[100,6]]},{id:'warm',name:'Higher CO₂,30°C',points:[[0,0],[20,2],[40,4],[60,6],[80,8],[100,9]]}];
export const greenhousePlans=[{id:'baseline',name:'Baseline',revenue:100,cost:25,rate:3},{id:'light',name:'Extra light',revenue:125,cost:45,rate:6},{id:'co2',name:'Extra CO₂',revenue:120,cost:35,rate:6},{id:'heat',name:'Extra heat',revenue:122,cost:42,rate:6},{id:'all',name:'All three',revenue:128,cost:60,rate:9}];
export const netReturn=p=>p.revenue-p.cost;
export function conservedPhoto(c,w,g,o){return c===6&&w===6&&g===1&&o===6;}
